      "sentences": [{"en":"He has a good sense of the absurd.","cn":"他对荒诞事物有较强的识别能力。"},{"en":"Of course it's not true, what an absurd idea.","cn":"那当然不合乎事实，这个想法太荒唐了！"},{"en":"His high-flown style just sounds absurd today.","cn":"他的浮夸风格如今听起来真是荒谬。"}],
      "phrases": [{"en":"theatre of the absurd","cn":"荒谬剧场；荒诞派戏剧"}],
      "synonyms": [{"pos":"adj.","words":["ridiculous","preposterous"],"cn":"荒谬的；可笑的"}]
