      "phrases": [{"en":"adjacent rock","cn":"围岩"},{"en":"adjacent structure","cn":"毗连建筑物"},{"en":"adjacent sea","cn":"近海；边缘海；邻海"},{"en":"adjacent side","cn":"邻边"},{"en":"adjacent channel","cn":"相邻信道"},{"en":"adjacent building","cn":"相邻建筑物"}],
